const nfpaTab = 2017691696;
const readyTab = 2017691697;

const nfpaData = await browser.read({ tabId: nfpaTab, maxChars: null });
const readyData = await browser.read({ tabId: readyTab, maxChars: null });

const findings = JSON.parse(await (await read("tmp://findings.json")).file.text());

findings.category1_fire = {
  source1: {
    name: "NFPA (National Fire Protection Association) - Home Fire Escape Planning",
    url: "https://www.nfpa.org/education-and-research/home-fire-safety/escape-planning",
    tabId: nfpaTab,
    key_points: [
      "Advance planning and working smoke alarms provide critical warning: as little as 1 to 2 minutes to escape safely once alarm sounds.",
      "Install smoke alarms in every sleeping room, outside each separate sleeping area, and on every level of the home.",
      "A closed door may slow the spread of smoke, heat, and fire (close doors behind you when escaping).",
      "Walk through the home to identify two ways out of each room (doors and windows).",
      "Establish an outside meeting place a safe distance in front of the home where everyone knows to meet.",
      "Make sure house/building number is clearly visible from the street so firefighters can find you quickly.",
      "Practice home fire escape drill at least twice a year during day and at night with everyone in household.",
      "Teach children how to escape on their own in case adults cannot reach or help them.",
      "Have a plan for anyone who needs assistance escaping (children, older adults, people with disabilities/pets).",
      "Get out and stay out; never go back inside for people or pets."
    ]
  },
  source2: {
    name: "Ready.gov (FEMA) - Home Fires",
    url: "https://www.ready.gov/home-fires",
    tabId: readyTab,
    key_points: [
      "Fire dynamics: can become life-threatening in 2 minutes, engulf home in 5 minutes; heat reaches 600°F at eye level vs 100°F at floor level.",
      "Smoke and toxic gases are the primary killers; fire produces blinding darkness.",
      "Working smoke alarms: test monthly, replace batteries twice a year (unless 10-year sealed lithium), replace smoke alarms every 10 years.",
      "Escape plan: practice 2-minute escape drill twice a year; two ways out of every room.",
      "Designate an outside meeting spot at a safe distance from home.",
      "Get out, stay out, call 911 from outside.",
      "Crawl low under smoke; feel doorknobs and door cracks with the back of your hand before opening.",
      "Fire extinguishers: PASS method (Pull, Aim, Squeeze, Sweep) only for small, contained fires with a clear exit path."
    ]
  },
  agreements: [
    "Fire spreads extremely quickly, leaving as little as 2 minutes to escape.",
    "Smoke alarms must be on every level, in sleeping areas, and tested regularly.",
    "Every room should have two identifiable ways out (primary door, secondary window/door).",
    "Designate a specific, fixed meeting location outside at a safe distance (e.g., tree, mailbox, front of home).",
    "Practice the escape plan at least twice a year.",
    "Get out and stay out—never re-enter a burning building for any reason; call emergency services once safely outside."
  ],
  differences_gaps: [
    "NFPA provides distinct practical instructions for children escaping independently if adults are cut off, and stresses visible street address numbers for emergency response.",
    "NFPA emphasizes closing interior doors behind you to slow fire/smoke propagation, whereas Ready.gov focuses more heavily on testing doorknobs with the back of the hand for heat before opening.",
    "Ready.gov includes specific guidance on fire extinguisher operation (PASS technique) and when it is safe to fight a fire vs. evacuate, whereas NFPA's escape planning page focuses purely on immediate egress.",
    "Ready.gov specifies replacing alarms after 10 years and replacing non-lithium batteries twice yearly; NFPA notes interconnected alarms are best so when one sounds, they all sound."
  ]
};

await write("tmp://findings.json", JSON.stringify(findings, null, 2));
console.log("Category 1 saved successfully.");

