findings.category3_reunification = {
  source1: {
    name: "Ready.gov (FEMA) - Make A Plan",
    url: "https://www.ready.gov/plan",
    tabId: 2017691700,
    key_points: [
      "4-step planning process: Step 1 Meet with family (discuss alert reception, shelter, evacuation, communication, kit update); Step 2 Assess household needs; Step 3 Document your plan; Step 4 Practice your plan.",
      "Customizing to specific daily needs: dietary, prescriptions/medical equipment, disabilities/functional needs, school-aged children, pets/service animals.",
      "Reconnection: Establish a family meeting place that is familiar and easy to find.",
      "Documentation: Fill out paper and digital family emergency communication cards including household contacts, meeting places, medical info.",
      "Tech readiness: Save important documents to cloud; know how to receive Wireless Emergency Alerts (WEA) and Emergency Alert System (EAS)."
    ]
  },
  source2: {
    name: "American Red Cross - Make a Plan (Disaster Preparedness Plan)",
    url: "https://www.redcross.org/get-help/how-to-prepare-for-emergencies/make-a-plan.html",
    tabId: 2017691701,
    key_points: [
      "Two specific meetup locations: (1) Right outside home for sudden emergencies (e.g. fire); (2) Outside neighborhood if unable to return home or ordered to evacuate.",
      "Out-of-area emergency contact: It may be easier to text or call long-distance when local phone lines are overloaded; everyone must carry contact info in writing and in cell phones.",
      "School & daycare coordination: Ensure children's care facilities have identical emergency contact numbers on file.",
      "Evacuation practice: Practice evacuating twice a year by grabbing emergency kit and driving primary and alternate evacuation routes plotted on paper and GPS.",
      "Special household circumstances: Plan for family members living elsewhere (deployed military, college students, frequent travelers).",
      "Pet evacuation: Keep list of pet-friendly hotels/shelters along evacuation routes ('If not safe for you, not safe for pets').",
      "Reconnect methods: Use Red Cross Emergency App and reconnecting protocols."
    ]
  },
  agreements: [
    "Designate designated meeting spots outside the immediate home and outside the immediate neighborhood.",
    "Appoint an out-of-area / out-of-state contact person because long-distance communication (especially text messaging) often works when local networks are jammed.",
    "Every family member must carry emergency contact information in physical written form (wallet cards) as well as stored digitally in cell phones.",
    "Coordinate contacts directly with schools, daycares, and workplaces.",
    "Regularly practice the communication and evacuation plan with all household members."
  ],
  differences_gaps: [
    "American Red Cross explicitly specifies the 'two meetup locations' formula (one immediate exterior spot + one regional/neighborhood exterior spot) and instructs families to physically drive alternate evacuation routes with their emergency kit twice yearly.",
    "Red Cross emphasizes planning for remote household members (college students, deployed military, frequent business travelers) and maintaining pet-friendly hotel directories.",
    "Ready.gov places greater structural emphasis on assessing access/functional needs, medical equipment dependencies, and cloud-safeguarding critical documents.",
    "Neither source provides a single unified digital sync standard between different mobile platforms, relying heavily on printable wallet cards and separate mobile apps."
  ]
};

await write("tmp://findings.json", JSON.stringify(findings, null, 2));
console.log("Category 3 saved. Now researching Category 4: First Aid and Poisoning.");

